// Hier alle Preise und Einstellungen pflegen.
// HINWEIS: Alle Preise sind Beispielwerte, nicht die echten Preise.
return [{
  json: {
    // Preise netto (19 % USt rechnet sevDesk)
    preisProBecher: 5,
    stundensatz: 15,          // pro Mitarbeitende:r und Stunde
    mitarbeiter: 2,
    aufAbbauStunden: 2,       // 1 h Aufbau + 1 h Abbau
    wochenendzuschlag: 50,    // Fr, Sa, So und Berliner Feiertage
    transportBerlin: 80, 
    transport50km: 150,
    transport100km: 250,

    pos1Name: 'Produkt – Becher',
    pos2Name: 'Service-Pauschale',
    steuersatz: 19,
    einheitBecherId: 1,       // sevDesk-Einheit "Stk"
    einheitPauschaleId: 1,    // sevDesk-Einheit für die Service-Pauschale

    benachrichtigungAn: 'deine.adresse@example.com',
    // Nur Formular-Anfragen im Label "Events", die noch nicht verarbeitet wurden, ab Starttag
    gmailSuche: 'label:events from:form-submission@squarespace.info -label:angebot-erstellt -label:angebot-fehlgeschlagen after:2026/09/25',
    labelErstellt: 'Angebot erstellt',
    labelFehlgeschlagen: 'Angebot fehlgeschlagen',
    sevdeskAngebotLink: 'https://my.sevdesk.de/om/detail/id/',
  }
}];

const cfg = $('Konfiguration').first().json;
const labels = $input.all().map(i => i.json);
const find = (name) => {
  const l = labels.find(x => (x.name || '').toLowerCase() === name.toLowerCase());
  if (!l) throw new Error('Gmail-Label "' + name + '" fehlt. Bitte in Gmail anlegen.');
  return l.id;
};
return [{ json: { labelErstellt: find(cfg.labelErstellt), labelFehlgeschlagen: find(cfg.labelFehlgeschlagen) } }];

// Liest die Squarespace-Formular-Mail aus und berechnet das Angebot.
// Wirft einen Fehler, wenn Pflichtangaben fehlen -> Fehlerzweig.
const cfg = $('Konfiguration').first().json;
const mail = $json;

// --- Text der Mail holen (Text-Teil bevorzugt, sonst HTML entschärfen) ---
let body = typeof mail.text === 'string' && mail.text.trim() ? mail.text : '';
if (!body) {
  body = String(mail.html || '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|tr|li|h\d)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&');
}
body = body.replace(/\r/g, '').replace(/\*/g, '');

const LABELS = {
  name: 'Name',
  email: 'E-Mail',
  datum: 'Wann findet euer Event statt\\?',
  gaeste: 'Wie viele Gäste erwartet ihr\\?',
  dauer: 'Wie lange sollen wir für euch rollen\\?',
  ort: 'Wo findet das Event statt\\?',
  nachricht: 'Nachricht',
};
const STOP = Object.values(LABELS).join('|') + '|Sent via form submission|Manage Submissions|Does this submission';

function feld(label) {
  const re = new RegExp('(?:^|\\n)[ \\t]*' + label + '[ \\t]*:?[ \\t]*([\\s\\S]*?)(?=\\n[ \\t]*(?:' + STOP + ')|$)', 'i');
  const m = body.match(re);
  return m ? m[1].trim() : '';
}

const fehlend = [];
const pflicht = (wert, name) => { if (!wert) fehlend.push(name); return wert; };

// --- Name ---
const nameRoh = pflicht(feld(LABELS.name).replace(/\s+/g, ' '), 'Name');
const teile = nameRoh.split(' ');
const vorname = teile.shift() || '';
const nachname = teile.join(' ');

// --- E-Mail ---
const emailM = feld(LABELS.email).match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
const email = pflicht(emailM ? emailM[0].toLowerCase() : '', 'E-Mail');

// --- Datum ---
const MONATE = { januar: 1, jan: 1, februar: 2, feb: 2, 'märz': 3, maerz: 3, marz: 3, 'mär': 3, april: 4, apr: 4, mai: 5, juni: 6, jun: 6, juli: 7, jul: 7, august: 8, aug: 8, september: 9, sep: 9, sept: 9, oktober: 10, okt: 10, november: 11, nov: 11, dezember: 12, dez: 12,
  january: 1, february: 2, march: 3, may: 5, june: 6, july: 7, october: 10, oct: 10, december: 12, dec: 12 };
const datumRoh = pflicht(feld(LABELS.datum), 'Eventdatum');
let tag, monat, jahr, m;
if ((m = datumRoh.match(/(\d{1,2})\.?\s+([A-Za-zÄÖÜäöü]+)\.?\s+(\d{4})/))) {
  tag = +m[1]; monat = MONATE[m[2].toLowerCase()]; jahr = +m[3];
} else if ((m = datumRoh.match(/(\d{1,2})\.(\d{1,2})\.(\d{4})/))) {
  tag = +m[1]; monat = +m[2]; jahr = +m[3];
} else if ((m = datumRoh.match(/(\d{4})-(\d{2})-(\d{2})/))) {
  jahr = +m[1]; monat = +m[2]; tag = +m[3];
}
const eventDatum = monat ? new Date(Date.UTC(jahr, monat - 1, tag)) : null;
if (datumRoh && (!eventDatum || eventDatum.getUTCDate() !== tag)) fehlend.push('Eventdatum (nicht lesbar: "' + datumRoh + '")');

// --- Gäste ---
const gaesteRoh = pflicht(feld(LABELS.gaeste), 'Gästezahl');
const gaesteM = gaesteRoh.match(/\d+/);
const gaeste = gaesteM ? parseInt(gaesteM[0], 10) : 0;
if (gaesteRoh && !gaeste) fehlend.push('Gästezahl (nicht lesbar: "' + gaesteRoh + '")');

// --- Dauer: Zahl oder Zeitspanne wie "18-22 Uhr" ---
const dauerRoh = pflicht(feld(LABELS.dauer), 'Dauer');
function stunden(s) {
  const t = s.toLowerCase().replace(/,/g, '.');
  const r = t.match(/(\d{1,2})(?:[:.](\d{2}))?\s*(?:uhr|h)?\s*(?:-|–|—|bis)\s*(\d{1,2})(?:[:.](\d{2}))?/);
  if (r) {
    const von = +r[1] + (r[2] ? +r[2] / 60 : 0);
    let bis = +r[3] + (r[4] ? +r[4] / 60 : 0);
    if (bis <= von) bis += 24; // über Mitternacht
    return Math.round((bis - von) * 100) / 100;
  }
  const z = t.match(/\d+(?:\.\d+)?/);
  return z ? parseFloat(z[0]) : 0;
}
const dauer = dauerRoh ? stunden(dauerRoh) : 0;
if (dauerRoh && !(dauer > 0)) fehlend.push('Dauer (nicht lesbar: "' + dauerRoh + '")');

// --- Ort / Transport ---
const ortRoh = pflicht(feld(LABELS.ort), 'Ort');
const ortKey = ortRoh.toLowerCase().replace(/\s+/g, '');
let transport = null;
if (ortKey.includes('100km')) transport = cfg.transport100km;
else if (ortKey.includes('50km')) transport = cfg.transport50km;
else if (ortKey.includes('inberlin')) transport = cfg.transportBerlin;
if (ortRoh && transport === null) fehlend.push('Ort (unbekannte Auswahl: "' + ortRoh + '")');

const nachricht = feld(LABELS.nachricht);

if (fehlend.length) {
  throw new Error('Anfrage unvollständig oder nicht lesbar: ' + fehlend.join(', '));
}

// --- Wochenende / Berliner Feiertage ---
function ostersonntag(y) {
  const a = y % 19, b = Math.floor(y / 100), c = y % 100, d = Math.floor(b / 4), e = b % 4;
  const f = Math.floor((b + 8) / 25), g = Math.floor((b - f + 1) / 3);
  const h = (19 * a + b - d - g + 15) % 30, i = Math.floor(c / 4), k = c % 4;
  const l = (32 + 2 * e + 2 * i - h - k) % 7, mm = Math.floor((a + 11 * h + 22 * l) / 451);
  const monat = Math.floor((h + l - 7 * mm + 114) / 31), tag = ((h + l - 7 * mm + 114) % 31) + 1;
  return Date.UTC(y, monat - 1, tag);
}
function feiertagBerlin(d) {
  const y = d.getUTCFullYear();
  const TAG = 86400000, ostern = ostersonntag(y);
  const liste = {
    [Date.UTC(y, 0, 1)]: 'Neujahr',
    [Date.UTC(y, 2, 8)]: 'Internationaler Frauentag',
    [ostern - 2 * TAG]: 'Karfreitag',
    [ostern + 1 * TAG]: 'Ostermontag',
    [Date.UTC(y, 4, 1)]: 'Tag der Arbeit',
    [ostern + 39 * TAG]: 'Christi Himmelfahrt',
    [ostern + 50 * TAG]: 'Pfingstmontag',
    [Date.UTC(y, 9, 3)]: 'Tag der Deutschen Einheit',
    [Date.UTC(y, 11, 25)]: '1. Weihnachtstag',
    [Date.UTC(y, 11, 26)]: '2. Weihnachtstag',
  };
  return liste[d.getTime()] || null;
}
const WOCHENTAGE = ['Sonntag', 'Montag', 'Dienstag', 'Mittwoch', 'Donnerstag', 'Freitag', 'Samstag'];
const wochentag = WOCHENTAGE[eventDatum.getUTCDay()];
const feiertag = feiertagBerlin(eventDatum);
const wochenende = [5, 6, 0].includes(eventDatum.getUTCDay()) || !!feiertag;

// --- Preise (netto) ---
const r2 = (x) => Math.round(x * 100) / 100;
const stundenGesamt = r2(dauer + cfg.aufAbbauStunden);
const personal = r2(stundenGesamt * cfg.mitarbeiter * cfg.stundensatz);
const zuschlag = wochenende ? cfg.wochenendzuschlag : 0;
const pos1 = r2(gaeste * cfg.preisProBecher);
const pos2 = r2(personal + transport + zuschlag);

const pos2Text = ['Personal', 'Transportkosten', 'Auf- und Abbau'].concat(wochenende ? ['Wochenendzuschlag'] : []).join('\n');
const pad = (n) => String(n).padStart(2, '0');
const datumDE = pad(tag) + '.' + pad(monat) + '.' + jahr;

return {
  json: {
    messageId: mail.id,
    vorname, nachname, name: nameRoh, email,
    eventDatum: datumDE, wochentag, feiertag,
    gaeste, dauerRoh, dauer, stundenGesamt,
    ort: ortRoh, nachricht,
    wochenende,
    rechnung: { pos1, personal, transport, zuschlag, pos2, nettoGesamt: r2(pos1 + pos2) },
    pos2Text,
    titel: 'Unverbindliches Angebot – Event am ' + datumDE,
  },
};

// 1. Suche per E-Mail  2. sonst per Name (genau 1 Treffer)  3. sonst neu anlegen
const a = $('Anfrage auslesen & berechnen').item.json;
const wege = $('sevDesk: E-Mail-Adressen laden').item.json.objects || [];
const personen = $json.objects || [];
const hinweise = [];
const norm = (s) => String(s || '').trim().toLowerCase();

const perMail = [...new Set(wege
  .filter(w => norm(w.value) === a.email && w.contact && w.contact.id)
  .map(w => String(w.contact.id)))];
if (perMail.length) {
  if (perMail.length > 1) hinweise.push('E-Mail ist bei ' + perMail.length + ' Kontakten hinterlegt, erster Treffer verwendet');
  return { json: { contactId: perMail[0], kontaktStatus: 'bestehender Kontakt (per E-Mail gefunden)', hinweise } };
}

if (!a.nachname) {
  hinweise.push('Kein Nachname angegeben: neuer Kontakt angelegt, mögliche Dublette bitte prüfen');
  return { json: { contactId: null, kontaktStatus: 'neu angelegt', hinweise } };
}

const perName = personen.filter(p => norm(p.surename) === norm(a.vorname) && norm(p.familyname) === norm(a.nachname));
if (perName.length === 1) {
  hinweise.push('Kontakt per Name gefunden, E-Mail weicht ab (' + a.email + '), bitte prüfen');
  return { json: { contactId: String(perName[0].id), kontaktStatus: 'bestehender Kontakt (per Name gefunden)', hinweise } };
}
if (perName.length > 1) hinweise.push(perName.length + ' Kontakte mit gleichem Namen vorhanden: neuer Kontakt angelegt, mögliche Dublette bitte prüfen');
return { json: { contactId: null, kontaktStatus: 'neu angelegt', hinweise } };

