parameters.jsCode:
const cfg = $('Konfiguration').first().json;
const a = $('Anfrage auslesen & berechnen').item.json;
const userId = $('sevDesk: Benutzer laden').first().json.objects[0].id;

// Angebotsnummer: sevDesk verlangt sie beim Anlegen per API, zählt den Nummernkreis dann aber nicht weiter.
// Daher: höhere von (nächste Nummer laut Nummernkreis) und (höchste vorhandene Nummer + 1).
const seq = $('sevDesk: Nummernkreis Angebote').item.json.objects || {};
const format = String(seq.format || 'AN-%NUMBER');
const pos = format.indexOf('%NUMBER');
const prefix = format.slice(0, pos).replace(/\[$/, '');
const suffix = format.slice(pos + 7).replace(/^\]/, '');
let hoechste = 0;
for (const o of ($('sevDesk: Bestehende Angebote laden').item.json.objects || [])) {
  const nr = String(o.orderNumber || '');
  if (!nr.startsWith(prefix) || !nr.endsWith(suffix)) continue;
  const mitte = nr.slice(prefix.length, nr.length - suffix.length);
  if (/^[0-9]+$/.test(mitte)) hoechste = Math.max(hoechste, parseInt(mitte, 10));
}
const naechste = Math.max(parseInt(seq.nextSequence, 10) || 1, hoechste + 1);
const nummer = prefix + naechste + suffix;
if (pos < 0 || nummer.includes('%')) throw new Error('Angebotsnummer konnte nicht gebildet werden (Format: ' + format + ')');

const heute = new Date().toISOString().slice(0, 10);
const order = {
  objectName: 'Order', mapAll: true,
  orderDate: heute,
  status: 100,                       // Entwurf
  orderType: 'AN',                   // Angebot
  header: a.titel,
  contact: { id: $json.contactId, objectName: 'Contact' },
  contactPerson: { id: userId, objectName: 'SevUser' },
  address: a.name,
  addressCountry: { id: 1, objectName: 'StaticCountry' },
  taxRule: { id: '1', objectName: 'TaxRule' },   // Umsatzsteuerpflichtige Umsätze
  taxType: 'default',
  taxText: 'Umsatzsteuer ' + cfg.steuersatz + '%',
  taxRate: 0,
  currency: 'EUR',
  version: 0,
  showNet: true,
};
order.orderNumber = nummer;

const body = {
  order,
  orderPosSave: [
    { objectName: 'OrderPos', mapAll: true, positionNumber: 1, name: cfg.pos1Name,
      quantity: a.gaeste, price: cfg.preisProBecher, taxRate: cfg.steuersatz,
      unity: { id: cfg.einheitBecherId, objectName: 'Unity' } },
    { objectName: 'OrderPos', mapAll: true, positionNumber: 2, name: cfg.pos2Name, text: a.pos2Text,
      quantity: 1, price: a.rechnung.pos2, taxRate: cfg.steuersatz,
      unity: { id: cfg.einheitPauschaleId, objectName: 'Unity' } },
  ],
  orderPosDelete: null,
};
return { json: { body, contactId: $json.contactId, kontaktStatus: $json.kontaktStatus, hinweise: $json.hinweise || [] } };

const cfg = $('Konfiguration').first().json;
const a = $('Anfrage auslesen & berechnen').item.json;
const v = $('Angebot vorbereiten').item.json;
const o = $('sevDesk: Angebot anlegen').item.json.objects.order;
const eur = (x) => x.toLocaleString('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' €';

const hinweise = [...v.hinweise];
const [t, m, j] = a.eventDatum.split('.').map(Number);
if (Date.UTC(j, m - 1, t) < Date.now() - 86400000) hinweise.push('Eventdatum liegt in der Vergangenheit');
if (a.dauer > 12) hinweise.push('Ungewöhnlich lange Dauer (' + a.dauer + ' h) – Eingabe war: "' + a.dauerRoh + '"');

const zeilen = [
  'Angebot zum Überprüfen steht in sevDesk bereit.',
  '',
  'Angebot: ' + (o.orderNumber || '(ohne Nummer)') + ' – ' + a.titel,
  'Link: ' + cfg.sevdeskAngebotLink + o.id,
  'Kunde: ' + a.name + ' (' + a.email + '), ' + v.kontaktStatus,
  'Event: ' + a.wochentag + ', ' + a.eventDatum + (a.feiertag ? ' (' + a.feiertag + ')' : '') + ' · ' + a.gaeste + ' Gäste · ' + a.dauer + ' h + ' + cfg.aufAbbauStunden + ' h Auf-/Abbau · ' + a.ort,
  'Summe netto: ' + eur(a.rechnung.nettoGesamt),
];
if (hinweise.length) zeilen.push('', 'Bitte prüfen:', ...hinweise.map(h => '- ' + h));
if (a.nachricht) zeilen.push('', 'Nachricht des Kunden:', a.nachricht);

return { json: { betreff: 'Angebot zum Überprüfen: ' + a.name + ', Event am ' + a.eventDatum, text: zeilen.join('\n') } };

const e = $json.error ?? $json;
let text = typeof e === 'string' ? e : (e.message || '') + (e.description ? ' – ' + e.description : '');
if (!text) text = JSON.stringify(e).slice(0, 1500);
let mail = {};
try { mail = $('Einzeln abarbeiten').item.json; } catch (x) { mail = $('Einzeln abarbeiten').first().json; }
return { json: {
  messageId: mail.id,
  betreff: 'FEHLER: Angebot konnte nicht erstellt werden – ' + (mail.subject || ''),
  text: [
    'Für eine Eventanfrage konnte kein Angebot erstellt werden.',
    '',
    'Schritt: ' + $prevNode.name,
    'Fehler: ' + text,
    '',
    'Die Mail hat das Label "Angebot fehlgeschlagen" bekommen und wird nicht erneut verarbeitet.',
    'Zum erneuten Versuch: Label in Gmail entfernen.',
    '',
    '--- Original-Anfrage ---',
    String(mail.text || '').slice(0, 3000),
  ].join('\n'),
} };
